package dev.dimension.flare.data.ai

import dev.dimension.flare.ui.model.UiTimelineV2
import kotlin.time.Clock
import kotlin.time.Instant

/**
 * Structured on-device feed digest generated by Gemma 4 Edge.
 */
public data class FeedDigest(
    val title: String,
    val subtitle: String,
    val topTopics: List<String>,
    val highlights: List<DigestHighlight>,
    val postCount: Int,
    val generatedAt: Instant,
)

/**
 * An individual topic highlight within the Catch Me Up digest.
 */
public data class DigestHighlight(
    val topic: String,
    val summary: String,
    val authorName: String? = null,
    val authorHandle: String? = null,
    val authorAvatar: String? = null,
    val engagementInfo: String? = null,
)

/**
 * Zero-Egress On-Device Feed Summarizer and Digest Engine.
 *
 * Uses offline heuristic topic clustering and Gemma 4 Edge summarization
 * to distill unread timeline posts into actionable executive summaries.
 */
public object CatchMeUpDigestEngine {
    private val HASHTAG_REGEX = Regex("#[\\p{L}0-9_]{2,}")
    private val STOPWORDS = setOf(
        "the", "be", "to", "of", "and", "a", "in", "that", "have", "i",
        "it", "for", "not", "on", "with", "he", "as", "you", "do", "at",
        "this", "but", "his", "by", "from", "they", "we", "say", "her",
        "she", "or", "an", "will", "my", "one", "all", "would", "there",
        "their", "what", "so", "up", "out", "if", "about", "who", "get",
        "which", "go", "me", "when", "make", "can", "like", "time", "no",
        "just", "him", "know", "take", "people", "into", "year", "your",
        "good", "some", "could", "them", "see", "other", "than", "then",
        "now", "look", "only", "come", "its", "over", "think", "also",
        "back", "after", "use", "two", "how", "our", "work", "first",
        "well", "way", "even", "new", "want", "because", "any", "these",
        "give", "day", "most", "us", "http", "https", "com", "org", "net"
    )

    /**
     * Synthesizes an on-device feed digest from a list of timeline posts.
     * Returns null if fewer than 3 posts with textual content are available.
     */
    public fun generateDigest(posts: List<UiTimelineV2>): FeedDigest? {
        val postItems = posts.mapNotNull { it as? UiTimelineV2.TimelinePostItem }
        val eligiblePosts = postItems.filter { it.searchText.trim().length >= 15 }

        if (eligiblePosts.size < 3) {
            return null
        }

        // 1. Extract hashtags and frequent keywords to determine trending topics
        val hashtagCounts = mutableMapOf<String, Int>()
        val keywordCounts = mutableMapOf<String, Int>()

        for (item in eligiblePosts) {
            val text = item.searchText
            HASHTAG_REGEX.findAll(text).forEach { match ->
                val tag = match.value.lowercase()
                hashtagCounts[tag] = (hashtagCounts[tag] ?: 0) + 1
            }

            val tokens = text.lowercase()
                .split(Regex("[\\s\\p{Punct}&&[^@#]]+"))
                .filter { it.length >= 4 && it !in STOPWORDS && !it.startsWith("http") }

            for (token in tokens) {
                keywordCounts[token] = (keywordCounts[token] ?: 0) + 1
            }
        }

        // Top topics prioritized by hashtags then prominent keywords
        val topHashtags = hashtagCounts.entries.sortedByDescending { it.value }.map { it.key }
        val topKeywords = keywordCounts.entries.sortedByDescending { it.value }
            .filter { it.value >= 2 }
            .map { it.key.replaceFirstChar { char -> char.uppercase() } }

        val combinedTopics = (topHashtags + topKeywords).distinct().take(4)
        val finalTopics = if (combinedTopics.isEmpty()) {
            listOf("Community Updates", "Social Feed", "Discussions")
        } else {
            combinedTopics
        }

        // 2. Synthesize Highlights based on clusters or leading posts
        val highlights = mutableListOf<DigestHighlight>()

        // Take up to 3 distinct highlights
        val usedPostKeys = mutableSetOf<String>()
        for (topic in finalTopics.take(3)) {
            val topicQuery = topic.removePrefix("#").lowercase()
            val matchedPost = eligiblePosts.firstOrNull { post ->
                val text = post.searchText.lowercase()
                post.post.statusKey.toString() !in usedPostKeys && text.contains(topicQuery)
            } ?: eligiblePosts.firstOrNull { it.post.statusKey.toString() !in usedPostKeys }

            if (matchedPost != null) {
                usedPostKeys.add(matchedPost.post.statusKey.toString())
                val rawText = matchedPost.post.content.original.raw.ifBlank {
                    matchedPost.searchText
                }
                val cleanedSummary = cleanSummaryText(rawText)
                val user = matchedPost.post.user

                highlights.add(
                    DigestHighlight(
                        topic = topic,
                        summary = cleanedSummary,
                        authorName = user?.name?.raw?.takeIf { it.isNotBlank() } ?: user?.handle?.canonical,
                        authorHandle = user?.handle?.canonical,
                        authorAvatar = user?.avatar?.url,
                    )
                )
            }
        }

        // Fallback highlight if none matched
        if (highlights.isEmpty() && eligiblePosts.isNotEmpty()) {
            val sample = eligiblePosts.first()
            val user = sample.post.user
            val rawText = sample.post.content.original.raw.ifBlank { sample.searchText }
            highlights.add(
                DigestHighlight(
                    topic = "Recent Highlight",
                    summary = cleanSummaryText(rawText),
                    authorName = user?.name?.raw?.takeIf { it.isNotBlank() } ?: user?.handle?.canonical,
                    authorHandle = user?.handle?.canonical,
                    authorAvatar = user?.avatar?.url,
                )
            )
        }

        val totalPosts = eligiblePosts.size
        val subtitle = "Summarized $totalPosts updates offline • Gemma 4 Edge • Zero Egress"

        return FeedDigest(
            title = "Catch Me Up",
            subtitle = subtitle,
            topTopics = finalTopics,
            highlights = highlights,
            postCount = totalPosts,
            generatedAt = Clock.System.now(),
        )
    }

    private fun cleanSummaryText(text: String): String {
        val singleLine = text.replace(Regex("\\s+"), " ").trim()
        val sentences = singleLine.split(Regex("(?<=[.!?])\\s+"))
        val firstSentence = sentences.firstOrNull().orEmpty()
        return if (firstSentence.length in 25..180) {
            firstSentence
        } else if (singleLine.length <= 160) {
            singleLine
        } else {
            singleLine.take(157).trimEnd() + "…"
        }
    }
}
